import{_ as t,o as d,c as o,a2 as l}from"./chunks/framework.DGu13UIe.js";const r="/bagent/lessons/50-delete-file/image.png",_=JSON.parse('{"title":"第 50 课 · delete_file 删除文件","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/50-delete-file/doc.md"},"headers":[],"relativePath":"chapters/50-delete-file.md","filePath":"chapters/50-delete-file.md"}'),a={name:"chapters/50-delete-file.md"};function i(c,e,s,n,h,g){return d(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="第-50-课-·-delete-file-删除文件" tabindex="-1">第 50 课 · delete_file 删除文件 <a class="header-anchor" href="#第-50-课-·-delete-file-删除文件" aria-label="Permalink to &quot;第 50 课 · delete_file 删除文件&quot;">​</a></h1><p><strong>约 15 分钟</strong> · <a href="/bagent/chapters/49-str-replace.html">第 49 课</a> 之后 · <strong>独立插件</strong></p><p>此前 Agent 能读、能写、能局部改，但<strong>不能删文件</strong>——清理废弃脚本、临时产物只能让用户自己动手。本课在 <a href="/bagent/chapters/49-str-replace.html">第 49 课</a> 之上增加 <strong><code>delete_file</code></strong>：在 cwd 下<strong>永久删除单个文件</strong>；路径限制与审批策略与 <code>write_file</code> / <code>str_replace</code> 相同。</p><p><img src="'+r+'" alt="delete_file 审批：Enter 允许 · Esc 拒绝"></p><p>上图：用户说「删一下 a.py」，侧栏弹出 <strong><code>delete_file</code> 红色审批</strong>（<code>Enter</code> 允许 · <code>Esc</code> 拒绝），批准后才真正 <code>unlink</code>。Agent 回一句「已删除」——用户夸「了不起」，它还在想「还有要搞的吗」……删文件这事，<strong>审批栏比客气话重要</strong>。</p><hr><h2 id="_1-安全提醒-动手前必读" tabindex="-1">1. 安全提醒（动手前必读） <a class="header-anchor" href="#_1-安全提醒-动手前必读" aria-label="Permalink to &quot;1. 安全提醒（动手前必读）&quot;">​</a></h2><p><code>delete_file</code> 调用的是系统级删除（<code>unlink</code>），<strong>删除后无法通过本插件恢复</strong>。误点批准、路径看错、Agent 理解错你的意图，都可能导致文件永久丢失。</p><p><strong>请只在可丢弃的测试目录里练习</strong>，例如：</p><ul><li>单独建一个空文件夹，如 <code>~/bagent-delete-playground/</code> 或 <code>lessons/50-delete-file/playground/</code></li><li>用 VS Code / Cursor <strong>只打开该文件夹</strong> 作为工作区（cwd 即测试目录）</li><li>在里面新建 <code>tmp-delete-me.txt</code> 等<strong>明确可删的临时文件</strong>再让 Agent 删除</li></ul><p><strong>不要</strong>在以下环境测试或让 Agent 删文件：</p><ul><li>个人文档、照片、下载目录、桌面上的重要文件</li><li>未提交或未推送的惟一代码副本、生产配置、数据库文件</li><li>公司项目主仓库里的真实业务代码（即使用户审批，风险仍由你承担）</li></ul><p>审批框是最后一道闸，<strong>不能代替你的判断</strong>：批准前务必看清 <code>path</code> 是否就是要删的那一个文件。本课为教学示例，<strong>不对任何数据丢失负责</strong>；在重要数据上启用删除能力前，请自行备份并确认版本管理（如 Git）可用。</p><hr><h2 id="_2-何时用-delete-file" tabindex="-1">2. 何时用 delete_file <a class="header-anchor" href="#_2-何时用-delete-file" aria-label="Permalink to &quot;2. 何时用 delete_file&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐工具</th></tr></thead><tbody><tr><td>用户明确说「删掉这个文件」</td><td><code>delete_file</code></td></tr><tr><td>清理临时文件、废弃测试产物</td><td><code>delete_file</code></td></tr><tr><td>只清空内容、文件还要留着</td><td><code>str_replace</code> 或 <code>write_file</code></td></tr><tr><td>删整个目录</td><td><strong>不支持</strong>（本课只删文件）</td></tr><tr><td>不确定路径对不对</td><td>先 <code>stat_file</code> 或 <code>read_file</code></td></tr></tbody></table><p>删除<strong>不可恢复</strong>。每次删除都会弹出红色审批框，用户拒绝则不会执行。</p><hr><h2 id="_3-参数与行为" tabindex="-1">3. 参数与行为 <a class="header-anchor" href="#_3-参数与行为" aria-label="Permalink to &quot;3. 参数与行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>path</code></td><td>要删除的<strong>文件</strong>绝对路径（必填）</td></tr></tbody></table><p>行为要点：</p><ul><li>仅删除<strong>普通文件</strong>；目标是目录 → 报错</li><li>文件不存在 → 明确报错</li><li>禁止 <code>.git</code>、<code>node_modules</code>、<code>.env</code> 及 cwd 外路径（与写工具一致）</li><li><strong>须用户审批</strong>（侧栏 danger 样式）</li><li>成功 → <code>{ &quot;ok&quot;: true, &quot;path&quot;: &quot;/abs/path/foo.ts&quot; }</code></li></ul><hr><h2 id="_4-代码位置" tabindex="-1">4. 代码位置 <a class="header-anchor" href="#_4-代码位置" aria-label="Permalink to &quot;4. 代码位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/deleteFile.ts</code></td><td><code>runDeleteFile()</code> — <code>unlinkSync</code></td></tr><tr><td><code>agent/tools.ts</code></td><td><code>delete_file</code> 定义、hook、<code>runTool</code></td></tr><tr><td><code>agent/system.ts</code></td><td>提示删文件用 <code>delete_file</code>、须审批</td></tr><tr><td><code>src/sidebar.ts</code></td><td><code>delete_file</code> 审批框 danger 样式</td></tr></tbody></table><p>第 49 课的 <code>str_replace</code>、第 48 课行号 <code>read_file</code> 等<strong>全部保留</strong>，本课只增量 <code>delete_file</code>。</p><hr><h2 id="_5-动手" tabindex="-1">5. 动手 <a class="header-anchor" href="#_5-动手" aria-label="Permalink to &quot;5. 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch50:compile</span></span></code></pre></div><ol><li>新建可丢弃目录，例如 <code>mkdir -p ~/bagent-delete-playground</code></li><li>用编辑器<strong>只打开该目录</strong>为工作区（不要打开整个 <code>bagent</code> 主仓库做删除实验）</li><li>打开 <strong><code>lessons/50-delete-file</code></strong> 子窗口 → <strong>F5</strong> 启动第 50 课插件（Extension Development Host 会继承当前工作区 cwd）</li><li>在测试目录里新建 <code>tmp-delete-me.txt</code>，让 Agent <code>delete_file</code> 删掉它 → 侧栏应出现<strong>红色</strong>审批框</li><li><strong>看清路径后再批准</strong>；批准后仅测试文件应消失。对目录、<code>.env</code> 等应报错</li></ol><p>终端调试：在测试目录下执行 <code>npm run ch50</code>（同样不要用重要项目目录作 cwd）。</p><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 是否在<strong>独立测试目录</strong>练习，未动重要文件？</li><li>[ ] <code>delete_file</code> 能删掉 cwd 下的普通文件？</li><li>[ ] 对目录、不存在路径、<code>.env</code> 会拒绝？</li><li>[ ] 审批框为 danger 样式（与 <code>write_file</code> 一致）？</li><li>[ ] <code>str_replace</code> / <code>read_file</code> 仍可用？</li></ul><hr><p><a href="/bagent/chapters/49-str-replace.html">← 第 49 课</a></p>',36)])])}const f=t(a,[["render",i]]);export{_ as __pageData,f as default};
